// from src/locales/ja/blog.ts. Body + FAQs for article 'add-text-to-image-guide' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>文字は、写真をメッセージに変えます。キャプションは写真が何を示すか説明し、タイトルは名前を与え、引用は声を与えます。</p>\n<p>画像に文字を入れるのは、シンプルなスキルですが使い道は多いです。SNSの投稿、ミーム、プレゼン、商品ラベル、注釈付きスクリーンショットは、すべて文字に頼っています。</p>\n<p>この記事では、文字をうまく入れる方法を解説します。フォント、サイズ、色、コントラスト、アウトライン、配置、そして文字を読めなくする失敗までカバーします。</p>\n<h2 id=\"what-text-on-image-does\">画像の文字が果たす役割</h2>\n<p>文字は、写真だけでは伝えられない意味を加えます。山の写真はただの山ですが、同じ写真にキャプションが付けば、思い出やジョーク、招待状になります。</p>\n<p>文字は文脈も加えます。日付や場所、名前を画像に書けば、見る人は別の説明なしに何を見ているかわかります。</p>\n<p>ビジネスでは、画像の文字はラベルです。価格の入った商品写真や、割引の入ったセールバナー、イベントの日付の入ったポスターは、すべて文字で売ります。</p>\n<p>大切なのは控えめにすることです。うまく置かれた数語は画像を強くしますが、写真に詰め込まれた段落は、説明したかったものそのものを隠してしまいます。</p>\n<h2 id=\"captions-vs-watermarks\">キャプション・タイトル・透かしは別の仕事</h2>\n<p>キャプションは画像を説明します。被写体の近くにあり、読みやすく、写真を見るすべての人に見てもらうためのものです。</p>\n<p>タイトルは画像に名前を付けます。たいていキャプションより大きく太く、ページや投稿のほかのすべての雰囲気を決めます。</p>\n<p>透かしは画像を守ります。持ち主を特定し、たいてい半透明で、コピーや再投稿に耐えるためのものです。</p>\n<p>3つを混同しないようにしましょう。透かしのように見えるキャプションは無視され、キャプションのように見える透かしは何も守りません。</p>\n<h2 id=\"fonts-explained\">フォント：雰囲気に合う書体を選ぶ</h2>\n<p>フォントは、言葉を読む前に文字の雰囲気を決めます。太いサンセリフはモダンで直接的に感じられ、セリフはクラシックでフォーマルに感じられます。</p>\n<p>画像に合うフォントを選びましょう。遊び心のあるミームには太くてがっしりしたフォントが必要で、結婚式の写真にはエレガントで軽いフォントが必要です。</p>\n<p>1枚の画像では、フォントは1〜2種類までにしましょう。たくさんの書体を混ぜるとごちゃごちゃに見えますが、1つの一貫したフォントはデザインをきれいでプロらしく保ちます。</p>\n<p>使うサイズでフォントを確認しましょう。大きいサイズでは美しく見える装飾フォントも、小さいサイズでは読めなくなることがあります。</p>\n<h2 id=\"text-size-scaling\">文字サイズ：小さい写真と大きい写真</h2>\n<p>文字サイズは、画像に対する割合で設定され、2パーセントから22パーセントまでです。だから、同じ設定が小さいサムネイルでも大きなカメラ写真でも同じように見えます。</p>\n<p>ピクセル単位で設定したサイズは、大きな写真では良く見えても、小さい写真では見えなくなることがあります。割合指定なら、この問題は起きません。</p>\n<p>見出しには、範囲の上のほうの大きいサイズを使いましょう。キャプションやクレジット行には、画像を支配せずに読みやすいままの小さいサイズを使います。</p>\n<p>共有する実際のサイズで文字を確認しましょう。フルサイズでは太く見える見出しも、SNSフィードのプレビューでは小さく見えることがあり、サムネイル用に決めたキャプションが大きなプリントでは目立つことがあります。</p>\n<h2 id=\"colour-and-contrast\">色とコントラスト：文字を読みやすくする</h2>\n<p>白い文字は暗い背景で、黒い文字は明るい背景で読めますが、ほとんどの写真は両方を含みます。1色だけでは、画像のどこかで必ず消えてしまいます。</p>\n<p>文字を読めるようにするのは、色そのものではなくコントラストです。明るい背景の明るい色は失敗し、暗い背景の暗い色も同じように失敗します。</p>\n<p>文字は、写真で最も無地の部分に置きましょう。晴れた空や空白の壁の上のキャプションは、忙しい群衆や森の上のものよりはるかに読みやすいです。</p>\n<p>無地の場所がないときは、背景パネルを加えましょう。白い文字の後ろの半透明の暗いボックスは、どこでも読めるようにしますが、画像をより多く覆います。</p>\n<h2 id=\"outline-and-shadow\">アウトラインとドロップシャドウ</h2>\n<p>アウトラインは、各文字の周りに描かれる縁です。白い文字の周りの細い暗いアウトラインは、明るい空でも読みやすく保ちます。だからミームはアウトラインを使います。</p>\n<p>ドロップシャドウは、文字を背景から持ち上げます。文字の後ろに柔らかい暗い縁を加え、アウトラインのような硬い見た目にならずに目立たせます。</p>\n<p>どちらか一方を使い、両方を最大限に使わないようにしましょう。アウトラインと強い影を組み合わせると、文字がごちゃごちゃに見えます。1つの効果だけならきれいなままです。</p>\n<p>クラシックなミームの文字には、太い暗いアウトラインの白い文字を使います。この組み合わせは、ほぼどんな背景でも読めるので、標準になりました。</p>\n<h2 id=\"positioning-and-layers\">配置とレイヤー</h2>\n<p>文字レイヤーは、画像のどこにでも動かせます。レイヤーをドラッグして配置し、複数あるときはツールで各レイヤーを別々に選択できます。</p>\n<p>上と下は、キャプションの定番の位置です。上の見出しと下のオチはミームの形式で、目が上から下へ読むのでうまくいきます。</p>\n<p>文字は端から離して置きましょう。境界に触れるキャプションは窮屈に見え、サービスは画面サイズごとに端をさらに切り取ることがよくあります。</p>\n<p>レイヤーが複数あるときは、変更する前に編集したいレイヤーを選択します。間違ったレイヤーを編集するのはよくある失敗で、どのレイヤーが有効か確認すれば簡単に避けられます。</p>\n<h2 id=\"rotating-text\">効果を出すための文字の回転</h2>\n<p>文字はカスタム角度で傾けられ、デザインにエネルギーを加えます。少し斜めの見出しはダイナミックに感じられ、まっすぐな文字は落ち着いてフォーマルに感じられます。</p>\n<p>回転は控えめに使いましょう。数度の小さな傾きは個性を加えますが、急な角度は文字を読みにくくし、ミスのように見えます。</p>\n<p>斜めの文字は、目を引くためのポスターやSNSグラフィックに適しています。明確さが最も大切な説明やラベルには向きません。</p>\n<p>回転した文字は、表示されるサイズで確認しましょう。フルサイズでは良く見える傾きが、フィードのプレビューでは小さい文字を読めなくすることがあります。</p>\n<h2 id=\"multi-line-text\">複数行のキャプション</h2>\n<p>文字の内容の中でEnterを押すと、新しい行ができます。1つのレイヤーで2〜3行にわたるキャプションを書け、行ごとに別のレイヤーを作る必要がありません。</p>\n<p>行は短くしましょう。画像の幅いっぱいに広がるキャプションは読みにくく、被写体を中心にした短い行は追いやすいです。</p>\n<p>行は、文章の自然な区切りで分けましょう。フレーズの真ん中での改行はぎこちなく感じますが、フレーズの間での改行は意図的に感じられます。</p>\n<p>ミームでは、上のキャプションに1つのレイヤー、下に1つのレイヤーを使います。別のレイヤーなら、各行を属する場所に正確に置けます。</p>\n<h2 id=\"memes\">ミームを作る</h2>\n<p>ミームは、短くて面白いキャプションの付いた写真で、たいてい上と下に太い暗いアウトラインの白い文字があります。形式はシンプルで、そのシンプルさがポイントです。</p>\n<p>文字は短くしましょう。段落の文字があるミームは面白くありません。ジョークの画像の段落は誰も読まないからです。上に1行、下に1行あれば十分です。</p>\n<p>太くてがっしりしたフォントを使いましょう。クラシックなミームの見た目は、小さいサイズでも忙しい背景でも読みやすい重いサンセリフを使います。</p>\n<p>上の行を先に、下の行をあとに置きます。目は上の設定を読み、画像を見てから、下のオチを読みます。</p>\n<h2 id=\"quotes-and-titles\">引用・タイトル・SNSグラフィック</h2>\n<p>写真の上の引用は、人気のSNS形式です。文字はたいてい大きく、中央に置かれ、画像の無地の部分か、暗くした背景の上に置かれます。</p>\n<p>引用は短くしましょう。1文のほうが段落よりはるかに効果的です。画像と文字がスペースを分け合い、どちらも支配してはいけません。</p>\n<p>タイトルには、キャプションより大きいサイズと太いフォントを使います。タイトルは目が最初に見つけるもので、画像はタイトルを支えるべきで、競うべきではありません。</p>\n<p>写真が忙しいときは、文字の後ろの画像を少し暗くします。半透明のオーバーレイは、写真を完全に隠さずに、白い文字を読めるようにします。</p>\n<h2 id=\"annotations\">注釈とラベル</h2>\n<p>注釈は、画像の部分を説明します。矢印付きのラベルや、番号付きのステップ、短いメモが、スクリーンショットを説明書に変えます。</p>\n<p>注釈は短く、説明するものの近くに置きましょう。被写体から遠いラベルは見る人を混乱させますが、すぐ隣のラベルは明らかです。</p>\n<p>1枚の画像のすべての注釈は、同じスタイルにしましょう。すべてのラベルで同じフォント、サイズ、色を使うと、画像はプロらしく、追いやすくなります。</p>\n<p>スクリーンショットに注釈を付けるときは、トリミングのあとに<a href=\"/ja/gazou-ni-tekisuto-tsuika/\">画像に文字を追加するツール</a>を使います。きつく切ったものに数個のはっきりしたラベルを付けたほうが、説明のないフルスクリーンショットよりはるかに役立ちます。</p>\n<h2 id=\"formats-and-export\">形式と書き出し</h2>\n<p>ツールはJPG、PNG、WebP、HEICなどの一般的な画像形式に対応し、ファイルは最大20MBまでです。必要に応じてJPG、PNG、WebPで書き出せます。</p>\n<p>PNGやWebPで書き出すと、元の画像の透明度が保てます。元が透明なPNGのステッカーなら、文字の書き出しでも透けた部分がそのまま残ります。</p>\n<p>文字入りの写真には、高画質のJPGが適しています。文字の端はJPGの圧縮で少し柔らかくなることがあるので、小さいキャプションでは画質を高く保ちましょう。</p>\n<p>画質スライダーはJPGとWebPの書き出しで表示され、PNGでは隠れます。PNGは可逆なので、調整する画質設定がないからです。</p>\n<h2 id=\"privacy-local-processing\">プライバシー：アップロードせずに文字を入れる</h2>\n<p>文字の編集はすべてブラウザの中で行われます。写真がサーバーにアップロードされることはないので、個人の写真や家族写真、仕事のスクリーンショットでは大切な点です。</p>\n<p>クラウドの編集ツールと比べると、これは本当の利点です。キャプション付きの家族写真を、数語加えるためだけに、見えないサーバーに送るべきではありません。</p>\n<p>ツールは書き出し時にEXIFのGPSデータも取り除きます。ツールからダウンロードしたキャプション付きの写真には、撮影場所の記録は残りません。</p>\n<p>文字のない元の写真を残しておきましょう。文字を書き出しに一体化させると、そのファイルからは取り除けないので、元だけがきれいなコピーです。</p>\n<h2 id=\"common-mistakes\">文字を入れるときのよくある失敗</h2>\n<p>最も多い失敗は、文字が小さすぎることです。フルサイズでは良く見えるキャプションも、画像がずっと小さく表示されるSNSフィードでは読めないことがあります。</p>\n<p>もうひとつの失敗は、コントラストの悪さです。明るい空の白い文字も、暗い背景の黒い文字も消えてしまうので、空白のキャンバスではなく、実際の写真で文字を確認しましょう。</p>\n<p>文字を書きすぎる人もいます。写真の上の段落は画像を隠し、見る人を圧倒しますが、よく選ばれた数語のほうがうまくいきます。</p>\n<p>最後に、サービスが切り取る場所に文字を置かないことです。SNSアプリは画面サイズごとに画像の端を切り取るので、大切な言葉は枠の内側にしっかり残しましょう。</p>\n<h2 id=\"text-on-product-photos\">商品写真の文字</h2>\n<p>商品写真には、短い文字が入ることがよくあります。価格や割引、特徴です。文字は大きく太く、商品自体を覆わない場所に置くべきです。</p>\n<p>価格や特典は角に置き、真ん中には置きません。角のラベルは商品を見えるままにしますが、中央のラベルは売っているものそのものを隠してしまいます。</p>\n<p>カタログ全体で一貫したスタイルを使いましょう。すべての価格ラベルで同じフォント、サイズ、色を使うと、ショップはプロらしく信頼できる印象になります。</p>\n<p>文字は短くしましょう。価格と1語、例えばセールや新商品で十分です。商品写真の上の段落は、買い手の注意を商品からそらします。</p>\n<p>手順の詳しい版は<a href=\"/ja/blog/gazou-ni-tekisuto-tsuika-yarikata/\">画像に文字を入れる方法</a>、読みやすさのルールは<a href=\"/ja/blog/gazou-no-tekisuto-yomiyasusa-kotsu/\">画像の文字：フォント・コントラスト・読みやすさ</a>をご覧ください。キャプションではなく所有権を示したいときは、<a href=\"/ja/gazou-suimaku/\">画像透かしツール</a>を試してみてください。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"写真の文字に最適なフォントは何ですか？","answer":"太いサンセリフが、ほとんどの写真で最も安全な選択です。小さいサイズでも忙しい背景でも読みやすいままです。セリフは結婚式の写真のようなフォーマルな画像に合い、装飾フォントは大きいサイズでのみ使えます。1枚の画像ではフォントは1〜2種類までにしましょう。"},{"question":"明るい写真で白い文字を読めるようにするには？","answer":"文字の周りに暗いアウトラインやドロップシャドウを付けると、明るい部分でも見えるままになります。写真で最も暗い部分の上に文字を置くのも効果的です。無地の場所がないときは、文字の後ろの半透明の暗いパネルが役立ちます。"},{"question":"画像に複数行の文字を入れられますか？","answer":"はい、入れられます。文字の内容の中でEnterを押すと、同じレイヤーに新しい行ができます。行ごとに別のレイヤーを加えることもできます。別のレイヤーなら、上のキャプションと下のキャプションを別々に配置でき、クラシックなミームのレイアウトになります。"},{"question":"文字を入れることと透かしを入れることの違いは何ですか？","answer":"文字を入れると、誰もが読むためのキャプションやタイトル、注釈ができます。透かしを入れると、コピーに耐えるための半透明の所有権マークができます。メッセージには文字ツール、保護には透かしツールを使いましょう。"},{"question":"SNS用の画像で、文字はどれくらいの大きさにすべきですか？","answer":"フルサイズだけでなく、小さいフィードのプレビューでも読めるほど大きくします。見出しは2〜22パーセントの範囲の上のほうのサイズが必要です。キャプションは小さくてもかまいません。フィードに表示されるサイズで画像を見て、結果をテストしましょう。"},{"question":"写真に文字を入れると位置情報は消えますか？","answer":"はい、ツールから書き出すとEXIFのGPSタグが取り除かれます。文字は画像に一体化し、位置情報の記録は同じステップで取り除かれます。そのデータを残したい場合は、元のファイルを保管しておきましょう。"}];
